//! OUTPUT htmlFor is a SameObject DOMTokenList with ordinary PutForwards.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for='first second first' class=stable>ready</output><input id=first value=first><input id=second value=second></form><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-html-for.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_html_for_canonical_descriptor_same_object_native_list_and_distinct_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),d=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'htmlFor');if(!d||typeof d.get!=='function'||typeof d.set!=='function'||!d.enumerable||!d.configurable||d.get.name!=='get htmlFor'||d.get.length!==0||d.set.name!=='set htmlFor'||d.set.length!==1||Object.hasOwn(output,'htmlFor'))throw 'canonical output token descriptor';var tokens=output.htmlFor;if(tokens!==output.htmlFor||tokens!==d.get.call(output)||tokens===output.classList||Object.getPrototypeOf(tokens)!==DOMTokenList.prototype||!(tokens instanceof DOMTokenList)||Object.prototype.toString.call(tokens)!=='[object DOMTokenList]'||tokens.value!=='first second first'||tokens.length!==2||tokens[0]!=='first'||tokens.item(1)!=='second'||tokens.item(2)!==null||tokens[2]!==undefined||Object.keys(tokens).join(',')!=='0,1'||Array.from(tokens).join(',')!=='first,second')throw 'actual native SameObject for tokens';var caught=false;try{tokens.supports('first');}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'no supported token set';for(var bad of [{},Object.create(HTMLOutputElement.prototype),document.getElementById('label'),document.createElement('div'),document.createElementNS('urn:foreign','output')]){caught=false;try{d.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine output token brand';}var count=0;for(var key in output)if(key==='htmlFor')count++;if(count!==1)throw 'inherited enumerable htmlFor';"#);}
#[test]
fn output_html_for_exact_tokens_mutate_for_without_class_or_label_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),tokens=output.htmlFor,classes=output.classList,labels=output.labels;output.setAttribute('for','A\ud800z A�z A\ud800z');if(tokens.length!==2||tokens[0]!=='A\ud800z'||!tokens.contains('A\ud800z')||!tokens.contains('A�z'))throw 'exact source token units';tokens.remove('A�z');tokens.add('B\udfffz','B\udfffz');if(tokens.value!=='A\ud800z B\udfffz'||!tokens.replace('A\ud800z','C\ud800z')||tokens.value!=='C\ud800z B\udfffz')throw 'exact token serialization';if(tokens.toggle('B\udfffz')||!tokens.toggle('D\ud800z',true)||tokens.value!=='C\ud800z D\ud800z')throw 'exact toggle';if(output.getAttribute('for')!==tokens.value||output.htmlFor!==tokens||output.classList!==classes||classes.value!=='stable'||output.labels!==labels||labels.length!==1||labels[0].control!==output||labels[0].form!==document.getElementById('owner'))throw 'independent native attributes and label authority';"#);}
#[test]
fn output_html_for_put_forwards_uses_ordinary_get_before_target_value_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),d=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'htmlFor'),tokens=output.htmlFor,order=[];d.set.call(output,{toString:function(){order.push('convert');return 'A\ud800z';}});if(tokens.value!=='A\ud800z'||order.join(',')!=='convert')throw 'native value setter conversion';var target={},value={marker:true},seen;Object.defineProperty(target,'value',{set:function(v){order.push('target');seen=v;},configurable:true});Object.defineProperty(output,'htmlFor',{get:function(){order.push('get');return target;},configurable:true});order=[];d.set.call(output,value);if(order.join(',')!=='get,target'||seen!==value||tokens.value!=='A\ud800z')throw 'ordinary Get then target Set with original value';Object.defineProperty(output,'htmlFor',{get:function(){return 7;},configurable:true});var calls=0,caught=false;try{d.set.call(output,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||tokens.value!=='A\ud800z')throw 'primitive forward target before conversion';delete output.htmlFor;output.htmlFor='fresh';if(output.htmlFor!==tokens||tokens.value!=='fresh')throw 'restored inherited forwarding';"#);}

#[test]
fn output_html_for_forwards_original_value_after_author_get_and_ignores_failed_set(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
'use strict';var subject=document.getElementById('output'),descriptor=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'htmlFor'),order='',value={toString:function(){order+='convert';return 'bad';}},seen,receiver;var target={set value(v){order+='set';seen=v;receiver=this;}};Object.defineProperty(subject,'htmlFor',{get:function(){order+='get';return target;},configurable:true});if(descriptor.set.call(subject,value)!==undefined||order!=='getset'||seen!==value||receiver!==target||subject.getAttribute('for')!=='first second first')throw 'original forwarded value';var symbol=Symbol();descriptor.set.call(subject,symbol);if(seen!==symbol)throw 'symbol passed unchanged';Object.defineProperty(target,'value',{value:'fixed',writable:false,configurable:true});descriptor.set.call(subject,value);if(target.value!=='fixed')throw 'nonwritable';Object.defineProperty(target,'value',{get:function(){return 'readonly';},configurable:true});descriptor.set.call(subject,value);if(target.value!=='readonly')throw 'getter only';var proxy=new Proxy({}, {set:function(t,k,v,r){if(k!=='value'||v!==value||r!==proxy)throw 'trap args';return false;}});target=proxy;descriptor.set.call(subject,value);target=Object.preventExtensions({});descriptor.set.call(subject,value);if(Object.hasOwn(target,'value'))throw 'nonextensible';target=3;try{descriptor.set.call(subject,value);throw 'primitive target';}catch(e){if(!(e instanceof TypeError))throw e;}var marker={};Object.defineProperty(subject,'htmlFor',{get:function(){throw marker;},configurable:true});try{descriptor.set.call(subject,value);throw 'getter abrupt';}catch(e){if(e!==marker)throw e;}target={set value(v){throw marker;}};Object.defineProperty(subject,'htmlFor',{get:function(){return target;},configurable:true});try{descriptor.set.call(subject,value);throw 'setter abrupt';}catch(e){if(e!==marker)throw e;}if(order.indexOf('convert')!==-1)throw 'premature conversion';delete subject.htmlFor;subject.htmlFor='recovered';if(subject.getAttribute('for')!=='recovered')throw 'native recovery';
"#);}

#[test]
fn output_html_for_live_iteration_observation_and_validation_keep_actual_for_record(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),t=output.htmlFor,a=output.getAttributeNode('for'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});t.toggle('first',true);t.replace('missing','last');if(watch.takeRecords().length||t.value!=='first second first')throw 'no-op preserves spelling and observation';t.value='A\ud800z A�z';t.remove('A�z');var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='first second first'||records[1].oldValue!=='A\ud800z A�z'||records[1].attributeName!=='for'||records[1].attributeNamespace!==null||a!==output.getAttributeNode('for')||a.value!==t.value)throw 'actual record observations';t.value='one two';var iterator=t.values();if(iterator.next().value!=='one')throw 'iterator first';t.add('three');if(iterator.next().value!=='two'||iterator.next().value!=='three'||!iterator.next().done)throw 'live native iterator';var seen=[];t.forEach(function(v,i,list){if(list!==t)throw 'callback list';seen.push(v);if(i===0)t.remove('two');});if(seen.join(',')!=='one,three')throw 'live callback';var calls='';try{t.add('',{toString:function(){calls+='convert';output.setAttribute('for','callback');return 'late';}});throw 'missing validation';}catch(e){if(e.name!=='SyntaxError')throw e;}if(calls!=='convert'||t.value!=='callback')throw 'conversion before validation';var marker={};try{t.value={toString:function(){output.setAttribute('for','effect');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(t.value!=='effect')throw 'completed author effects';"#);}
#[test]
fn output_html_for_inert_clone_adoption_no_main_slots_and_typed_handle_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('output');source.htmlFor='A\ud800z A�z';var list=source.htmlFor,copy=source.cloneNode(true),copied=copy.htmlFor,attr=copy.getAttributeNode('for'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);copied.remove('A�z');copied.add('B\udfffz');if(String(copied)!=='A\ud800z B\udfffz'||copied.item(1)!=='B\udfffz'||Array.from(copied).join(',')!=='A\ud800z,B\udfffz'||copy.htmlFor!==copied||list===copied||copied.value!=='A\ud800z B\udfffz'||list.value!=='A\ud800z A�z'||attr.value!==copied.value||attr.ownerDocument!==target||copy.ownerDocument!==target||source.classList.value!=='')throw 'inert exact clone adoption';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();assert!(p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("Import supports ordinary HTML containers"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.node_limit=d.nodes.len();p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('output'),held=isolated.htmlFor;held.value='X\ud800z';held.add('Y\udfffz');if(isolated.htmlFor!==held||held.length!==2||held.value!=='X\ud800z Y\udfffz')throw 'inert source without main slots';var div=owner.createElement('div');"#);
for expression in ["div;","document.getElementById('label');"]{let Value::Host(owner)=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let forged=script_class_list::output_for_handle(owner);let before=(p.state.retained,p.state.dom_commits);let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(!bridge.class_list_receiver(forged));assert!(bridge.class_list_get(forged,"length").is_err());assert!(bridge.class_list_set(forged,"value",Value::String("bad".into())).is_err());assert_eq!((bridge.state.retained,bridge.state.dom_commits),before);}
}
#[test]
fn output_html_for_native_and_inert_refusals_preserve_records_and_recover(){for inert in [false,true]{for expression in [r#"list.value='long A\ud800z B\udfffz';"#,r#"list.add('longA\ud800z');"#,r#"output.htmlFor='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.htmlFor='seed';var list=output.htmlFor,attr=output.getAttributeNode('for'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('output'),list=output.htmlFor;list.value='seed';var attr=output.getAttributeNode('for'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(list.value!=='seed'||attr.value!=='seed'||watch.takeRecords().length)throw 'atomic refused token write';list.value='fresh';if(output.htmlFor!==list||attr!==output.getAttributeNode('for')||attr.value!=='fresh'||watch.takeRecords().length!==1)throw 'fresh exact token recovery';");}}}}
#[test]
fn output_html_for_saved_child_origin_precedes_author_get_and_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'htmlFor'),list=output.htmlFor,calls=0;Object.defineProperty(output,'htmlFor',{get:function(){calls++;return list;},configurable:true});descriptor.set.call(output,'A\ud800z');if(calls!==1||descriptor.get.call(output)!==list)throw 'saved child accessor';calls=0;"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-tokens.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("descriptor.set.call(output,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://output-html-for.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||list.value!=='A\\ud800z')throw 'origin ordering';descriptor.set.call(output,'fresh');if(calls!==1||list.value!=='fresh')throw 'fresh captured origin recovery';");}

#[test]
fn output_html_for_getter_and_paid_reads_keep_identity_and_recover(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.htmlFor='A\\ud800z B\\udfffz';var list=output.htmlFor;"}else{"var output=document.getElementById('output');output.htmlFor='A\\ud800z B\\udfffz';var list=output.htmlFor;"});let Value::Host(owner)=p.runtime.execute("output;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let retained=p.state.retained;let commits=p.state.dom_commits;let limit=p.state.retained_limit;p.state.retained_limit=retained;let Value::Host(list)=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_html_for_get(owner).unwrap()else{panic!()};assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));for mode in 0..4{p.begin_job();p.state.retained_limit=limit;match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));}p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.htmlFor!==list||list[0]!=='A\\ud800z'||list[1]!=='B\\udfffz')throw 'fresh paid token read recovery';");}}
